"use strict";(globalThis.webpackChunksite=globalThis.webpackChunksite||[]).push([[3200],{5747(e,t,n){n.r(t),n.d(t,{assets:()=>h,contentTitle:()=>r,default:()=>c,frontMatter:()=>i,metadata:()=>o,toc:()=>d});var o=n(250),a=n(4848),s=n(8453);const i={title:"Earth phase, 6x mainnet throughput without even trying",description:"Forty-one days of MusashiNet's Earth phase \u2014 what the first public Leios testnet phase proved, what broke, how it was fixed in the open, and what comes next in Water.",slug:"musashinet-earth-phase",authors:["carlos"],tags:["testnet","musashinet","leios","throughput"]},r=void 0,h={authorsImageUrls:[void 0]},d=[{value:"TLDR",id:"tldr",level:2},{value:"What Earth gave us",id:"what-earth-gave-us",level:2},{value:"From paper to prototype",id:"from-paper-to-prototype",level:2},{value:"Five throws in the Dojo",id:"five-throws-in-the-dojo",level:2},{value:"Leaks, crashes, and forks made for an interesting week",id:"leaks-crashes-and-forks-made-for-an-interesting-week",level:3},{value:"BROKEN, DO NOT USE",id:"broken-do-not-use",level:3},{value:"It&#39;s the mempool, stupid",id:"its-the-mempool-stupid",level:3},{value:"The day we forked it up!",id:"the-day-we-forked-it-up",level:3},{value:"The morning every machine stopped",id:"the-morning-every-machine-stopped",level:3},{value:"The red team is already inside",id:"the-red-team-is-already-inside",level:2},{value:"Water: same design, many configurations",id:"water-same-design-many-configurations",level:2}];function l(e){const t={a:"a",admonition:"admonition",blockquote:"blockquote",em:"em",h2:"h2",h3:"h3",img:"img",li:"li",p:"p",strong:"strong",ul:"ul",...(0,s.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.h2,{id:"tldr",children:"TLDR"}),"\n",(0,a.jsx)(t.p,{children:"Earth, the first phase of MusashiNet, the Leios public testnet, asked whether the prototype holds in the wild. Forty-one days later, the answer is yes."}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Six times mainnet's ceiling."})," MusashiNet peaked at 26.8 TxkB/s with Leios active, against the 4.51 TxkB/s Cardano mainnet can reach with Praos alone. That's 6x mainnet's current maximum throughput."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"The whole protocol ran end to end, in public."})," More than 127,000 blocks, 30,000 endorser blocks announced, nearly 8,000 certificates on chain, 63 pools registered, and 10 releases in 6 weeks."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Five incidents, zero design failures."})," A memory leak, two forks, frozen syncs, a one-byte serialization disagreement and a network-wide halt, all related to bugs, found and fixed in the open. The design proved to be correct."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"The red team is already inside."})," Piranha attacks the network with our published threat model in hand; so far Leios degrades in proportion to attacker stake, and the safety of the Praos layer remains untouched."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Water phase just started."})," A fresh chain for parameter exploration, a redesigned mempool and real BLS keys, with the rewards program live, including retroactive rewards for pools that forged and voted in Earth."]}),"\n"]}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.a,{href:"/blog/why-leios",children:"Last time"}),", we talked about why Cardano needs Leios and introduced MusashiNet, the Dojo where the protocol trains: five phases from Musashi's ",(0,a.jsx)(t.em,{children:"Book of Five Rings"})," (Earth, Water, Fire, Wind, Void) and two swords, the short sword of Praos blocks and the long sword of endorser blocks. Earth, the first phase, has now closed. This is its story."]}),"\n",(0,a.jsx)(t.h2,{id:"what-earth-gave-us",children:"What Earth gave us"}),"\n",(0,a.jsxs)(t.p,{children:["The Earth phase asked one question: ",(0,a.jsx)(t.strong,{children:"does the prototype hold in the wild, at real latencies, on machines we neither control nor can see?"})," Holding meant running the whole protocol end-to-end: Praos blocks produced, endorser blocks announced, the stake voting on them, certificates landing on chain. The numbers that follow are that checklist, ticked."]}),"\n",(0,a.jsx)(t.p,{children:"Forty-one days. More than 127,000 blocks, 30,000 endorser blocks announced, nearly 8,000 certificates carried on chain. Sixty-three pools registered over the phase, up from the three we started with, forty producing blocks in a single epoch at the peak. Twelve releases in eight weeks, an unbroken weekly cadence that absorbed two same-week hotfixes without missing the next release."}),"\n",(0,a.jsxs)(t.p,{children:["A young testnet has no traffic of its own, so we brought our own. The ",(0,a.jsx)(t.strong,{children:"centrifuge"}),", our synthetic load generator, was tuned to push slightly more transactions than Praos could clear on its own, and the protocol's settings stayed at cautious first values. It ran one hour on, one hour off. Twelve hours a day, every day, the network lived in the conditions Leios was built for."]}),"\n",(0,a.jsx)(t.p,{children:"That was enough for a first test of the design at a global scale. MusashiNet peaked at 26.8 TxkB/s with Leios active, against the 4.51 TxkB/s Cardano mainnet can reach with Praos alone at today's parameters. Six times today's ceiling, with the dials barely turned. In the final days of the phase, when things were more stable, Leios was carrying 54% of everything that reached the chain."}),"\n",(0,a.jsx)(t.p,{children:"Compared with the traffic the mainnet actually carried over the same period, the Earth phase moved 18x the transaction count and 3.3x the bytes."}),"\n",(0,a.jsx)(t.h2,{id:"from-paper-to-prototype",children:"From paper to prototype"}),"\n",(0,a.jsxs)(t.p,{children:["Leios started as a research paper: ",(0,a.jsx)(t.a,{href:"https://eprint.iacr.org/2025/1115.pdf",children:"High-Throughput Blockchain Consensus under Realistic Network Assumptions"}),", presented at Crypto 2025. A paper is not a specification, so the engineering team turned it into ",(0,a.jsx)(t.a,{href:"https://github.com/cardano-foundation/CIPs/tree/master/CIP-0164",children:"CIP-164"}),", Linear Leios, a variant that could be built in reasonable time with the least disruption to the protocol Cardano already runs. The proposal evolved for months in the open, shaped by community discussion and backed by simulations, before it merged on January 6, 2026."]}),"\n",(0,a.jsxs)(t.p,{children:["A working prototype followed in under six months. ",(0,a.jsx)(t.strong,{children:"Sebastian Nagel"}),", the Leios architect, is leading the team that carried it across: a pragmatic, experienced engineer who knows Cardano inside out and is a productivity machine."]}),"\n",(0,a.jsx)(t.p,{children:"The goal is openly ambitious: Leios mainnet-ready by the end of the year. Consensus upgrades are usually measured in years. Going from specification to mainnet in a single year would make this among the fastest the industry has seen, and we are chasing it in the open, release by release."}),"\n",(0,a.jsx)(t.h2,{id:"five-throws-in-the-dojo",children:"Five throws in the Dojo"}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.img,{src:n(220).A+"",width:"1712",height:"1152"})}),"\n",(0,a.jsx)(t.p,{children:"As expected, not everything was smooth. We found bugs, forked the chain twice, and had a morning when every machine on the network stopped. None of it was a protocol failure. Every one of those was a bug in our code."}),"\n",(0,a.jsx)(t.p,{children:"We fixed every one of them, learned from them, and moved on. Five of them are worth telling, in the order they found us."}),"\n",(0,a.jsx)(t.h3,{id:"leaks-crashes-and-forks-made-for-an-interesting-week",children:"Leaks, crashes, and forks made for an interesting week"}),"\n",(0,a.jsxs)(t.p,{children:["On the Thursday of launch week, ",(0,a.jsx)(t.strong,{children:"John Lotoski"}),", our system reliability node team lead, spotted the node leaking memory. Consistent across all three of our block producers."]}),"\n",(0,a.jsx)(t.p,{children:"Containment first: a daily restart on every machine; then a profiled build on one relay to catch it in the act."}),"\n",(0,a.jsx)(t.p,{children:"In the community channel, people were noticing it too:"}),"\n",(0,a.jsx)(t.admonition,{title:"Kiwipool | June 29",type:"note",children:(0,a.jsxs)(t.p,{children:['"',(0,a.jsxs)(t.em,{children:["Noticed after 2 -3 days soak running the nodes RAM is up around 4.5GB ",(0,a.jsx)("br",{}),"\nWhat sort of RAM usage y'all seeing?"]}),'"']})}),"\n",(0,a.jsx)(t.p,{children:"It was our leak, being measured from the outside. To make it more interesting, that weekend, under the centrifuge's load, the chain forked. Twice!"}),"\n",(0,a.jsx)(t.p,{children:"The forks were the easy part. The crashes were the killer: any node that met a certified block without having the endorser data died on the spot, and reviving it meant a human walking a database directory over to it. So John spliced the chain back together by hand, twice, and ran the experiment. Load off: healed within hours. Load on: collapse, on schedule."}),"\n",(0,a.jsx)(t.p,{children:"Why the chain broke under load was still an open question. We had a suspect: in the lab, on a three-node devnet, block production had slowed as the mempool filled. That needed further investigation."}),"\n",(0,a.jsx)(t.p,{children:"The next morning John cornered the leak. Under load, the node opened a fresh connection to its Leios database over and over and never let one go, each holding its file handle and two megabytes of cache: 173 handles an hour, a relay's entire memory in about a day. The fix taught the node to close what it opens. The crash fix changed the block header format, so, days later, we retired that first chain, and its successor kept its genesis block until the very end of the phase."}),"\n",(0,a.jsx)(t.p,{children:"That is week one in the Dojo. You get thrown, you learn the fall, you get up."}),"\n",(0,a.jsx)(t.h3,{id:"broken-do-not-use",children:"BROKEN, DO NOT USE"}),"\n",(0,a.jsx)(t.p,{children:"The next throw came in week two, with the release that enabled real Leios certificates: transactions were now endorsed in a block only once 75% of the stake had voted for them."}),"\n",(0,a.jsx)(t.p,{children:"The next afternoon, the chain announced its first endorser block. The long sword's first swing."}),"\n",(0,a.jsx)(t.p,{children:"Three operators posted the same number: fresh syncs were freezing at block 28,358. Then the nodes started segfaulting."}),"\n",(0,a.jsx)(t.p,{children:"Two failures, with terrible timing. Sebastian was due on a fourteen-hour flight to Tokyo to talk Leios with Japanese stake pool operators (SPOs) and delegated representatives (DReps) at WebX. He threw in some ideas, handed over the incident, and went to the airport."}),"\n",(0,a.jsx)(t.p,{children:"Luckily, we have a badass team!"}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"Dra\u017een Popovi\u0107"}),", one of our consensus engineers, a Haskell wizard with a strong cybersecurity background, turned the incident thread into a control tower: numbered updates, on the hour, each saying what was found, what was fixed, what was still broken, and what came next. Within two hours he had a hypothesis for the segfault cascade, a fix branch built, and a patched node rolling out."]}),"\n",(0,a.jsx)(t.p,{children:"Then came UPDATE 3:"}),"\n",(0,a.jsx)(t.admonition,{title:"Dra\u017een Popovi\u0107 | UPDATE 3",type:"note",children:(0,a.jsxs)(t.p,{children:["Bad news ",(0,a.jsx)("br",{}),"\nThe patch killed the segfaults, but fresh syncs are still freezing at block 28,358."]})}),"\n",(0,a.jsx)(t.p,{children:"John put the patched node under full centrifuge load for 90 minutes, with zero segfaults, and that fix shipped while Sebastian was still in the air. The freeze fought on."}),"\n",(0,a.jsxs)(t.p,{children:["The frozen syncs took more forensics. ",(0,a.jsx)(t.strong,{children:"Nick Frisby"}),", a consensus engineer from ",(0,a.jsx)(t.strong,{children:"Tweag by Modus Create"}),", and one of the most knowledgeable people about Cardano internals, opened an investigation."]}),"\n",(0,a.jsx)(t.p,{children:"Forty minutes in, Nick had that first bug: block 28,358 had announced the chain's first endorser block, block 28,359 carried its certificate, and a syncing node would download every block that followed yet could select none of them, because one check deep in the code reported \u2018no certificate here\u2019 no matter what the block said. The chain's first swing of the long sword had locked the front door behind it."}),"\n",(0,a.jsx)(t.p,{children:"Soon he found a second bug, a cleanup routine deleting endorser blocks that arrived before their announcing block. By late afternoon he had a third, more fundamental than either: the node would sometimes throw a request away instead of sending it, then count it as sent anyway, until it believed it was too busy to ask for anything more. All three fixes were pushed, with his own build syncing the whole testnet end-to-end to be sure. Three bugs, one working day."}),"\n",(0,a.jsx)(t.p,{children:"Sebastian landed to find the segfaults solved and shipped, and the stall understood and fixed in a branch."}),"\n",(0,a.jsxs)(t.p,{children:["The big ",(0,a.jsx)(t.a,{href:"https://github.com/input-output-hk/ouroboros-leios/releases/tag/prototype-2026w27",children:"warning sign"})," is still there: \u2018Prototype 2026w27 \u2013 BROKEN, DO NOT USE.\u2019"]}),"\n",(0,a.jsx)(t.h3,{id:"its-the-mempool-stupid",children:"It's the mempool, stupid"}),"\n",(0,a.jsx)(t.p,{children:"The suspect from the lab and from week one had still never been caught in the act. It required long periods of sustained full load to manifest, and the chain was finally steady enough to bear it again."}),"\n",(0,a.jsxs)(t.p,{children:["Sebastian posted the invitation in the community channel: stability issues resolved, come load the network yourselves. And he shipped the tool to do it: ",(0,a.jsx)(t.strong,{children:"tx-firehose"}),", a generator he wrote over a weekend, as powerful as our centrifuge and easier to use."]}),"\n",(0,a.jsxs)(t.p,{children:["The community showed up. Kiwipool aimed theirs from New Zealand, ten transactions a second, then thirty, until their wallet ran dry. ",(0,a.jsx)(t.strong,{children:"Leon"})," of ",(0,a.jsx)(t.strong,{children:"HAPPY"})," burned a thousand test ada in a few runs. Of course, it is called a firehose for a reason! We refilled their wallets so they could keep testing."]}),"\n",(0,a.jsx)(t.p,{children:"It worked. For the first time on MusashiNet, the mempool stayed full for ten hours straight, topped up by transactions arriving faster than Praos could clear them, half the traffic ours and half the community's."}),"\n",(0,a.jsx)(t.p,{children:"And the problem showed. Blocks began running late. On mainnet, with a more complex topology, virtually every block reaches every node within a second of being forged. On MusashiNet that day, more than 40% of blocks took longer, and 10% were still in transit after three seconds."}),"\n",(0,a.jsx)(t.p,{children:"Memory was the first suspect, but the garbage-collection numbers stayed flat all day. The network was next, but diffusion seemed to be working correctly, and one late block settled it: it left its origin relay 3.467 seconds late, then reached every route within tenths of a second of the first arrival. Born late, then relayed fast. The delay was at the block production stage, not in transit."}),"\n",(0,a.jsx)(t.p,{children:"Final suspect: the forge loop. It opens by asking the mempool for a snapshot of the waiting transactions, and under full load, an operation that normally returns in milliseconds took seconds."}),"\n",(0,a.jsx)(t.p,{children:"We had the smoking gun. It was the mempool! Designed for Praos, it revalidates all transactions every time a node adopts a block, while holding a lock the forge loop needs. The fuller the mempool, the longer every producer waits for its own block to be forged. In the extreme, they waited past their own leadership slots."}),"\n",(0,a.jsx)(t.p,{children:"Scaling up our own machines improved forging to a third of a second on the heaviest day of load. But that is not the right solution: every gigabyte we ask for comes out of operators' pockets, so the fix belongs in code, not hardware. The team has redesigned the mempool to revalidate off-chain, so forging never queues behind bookkeeping, and the Water phase is where it will get tested."}),"\n",(0,a.jsx)(t.h3,{id:"the-day-we-forked-it-up",children:"The day we forked it up!"}),"\n",(0,a.jsxs)(t.p,{children:["Early one morning in week four, the network split at block 67,554, producers rejecting everything the relays offered. ",(0,a.jsx)(t.strong,{children:"VOLCY"})," posted their logs: the next block was failing validation on a size mismatch, 66,006 bytes against a declared 66,007."]}),"\n",(0,a.jsx)(t.p,{children:"The fork was caused by that one byte."}),"\n",(0,a.jsx)(t.p,{children:"A block producer running another node implementation had forged a perfectly valid block. Haskell nodes accepted it, decoded it, and wrote it back to disk one byte shorter, a slightly different binary convention. Same transactions, same meaning, different bytes, wrong hash."}),"\n",(0,a.jsxs)(t.p,{children:["The other implementation did nothing wrong. The Haskell node changed the bytes. We have had a rule against this for almost a decade: ",(0,a.jsx)(t.strong,{children:"never re-serialize another node's data"}),", because with more than one implementation on a network, there is no such thing as an innocent re-encoding. We broke our own rule, moving fast in a young era's codec, and the network penalized us immediately."]}),"\n",(0,a.jsx)(t.p,{children:"Nick Frisby came back the same day with a fix: he stopped the node from altering block bytes on their way to disk and had it quietly repair the mangled ones still arriving, deliberately temporary while the real serialization fix was built where it belonged, upstream in the ledger. Chain density climbed back out of the hole."}),"\n",(0,a.jsxs)(t.p,{children:["Independent node implementations agreeing byte-for-byte on every block is the ultimate correctness test. The one time agreement broke, it broke by a single byte. A reminder to keep the ",(0,a.jsx)(t.a,{href:"https://github.com/cardano-scaling/cardano-blueprint",children:"cardano-blueprint"})," project up to date, and evidence that conformance tests will be more important as we approach the Leios release to mainnet."]}),"\n",(0,a.jsx)(t.h3,{id:"the-morning-every-machine-stopped",children:"The morning every machine stopped"}),"\n",(0,a.jsxs)(t.p,{children:["Week six opened with a big change for SPOs: real BLS keys. Until then, the keys that let a pool vote in Leios had been derived automatically, training wheels everyone knew were temporary. ",(0,a.jsx)(t.strong,{children:"Thomas Vellekoop"}),", one of our cryptographic engineers, had finalized the BLS implementation and had it independently audited months before. Now thw BLS registration was completely integrated in node, ledger, api, and cli. Operators started submitting key registrations on chain, and voting was moving onto the machinery mainnet will use."]}),"\n",(0,a.jsx)(t.p,{children:"Then, one morning at 10:42 UTC, every machine on the network stopped."}),"\n",(0,a.jsx)(t.p,{children:"Not slowed. Stopped. An external experimental node had forged a block carrying a Leios certificate with an invalid signature. Input like that deserves the adversarial treatment: reject the block, disconnect the peer, carry on. Our code treated the invalid certificate as a fatal error instead, and every node that saw the block died on it; any node that restarted met the same block and died again. John's status report was six words long: \u2018All machines affected, all machines stopped.\u2019"}),"\n",(0,a.jsx)(t.p,{children:"One malformed signature shut the network down."}),"\n",(0,a.jsx)(t.p,{children:"Fifty minutes after the halt, a patched node was built and deployed across our infrastructure for testing. We posted the public notice within two hours of the first crash, with working guidance for operators. The permanent fix merged the next day, and it is as much a one-line philosophy as a patch: a bad block from the outside world becomes a logged rejection, never a dead process. A network node's job is to survive what strangers send it."}),"\n",(0,a.jsx)(t.p,{children:"The hotfix release went out the morning after, and Sebastian battle-tested it on his own block producer before recommending it to anyone else."}),"\n",(0,a.jsxs)(t.p,{children:["As the machines came back to life, the community continued registering keys. ",(0,a.jsx)(t.strong,{children:"PET"})," registered a BLS key on the day of the outage itself, ",(0,a.jsx)(t.strong,{children:"BIKES"})," was forging on the patched release within hours, and ",(0,a.jsx)(t.strong,{children:"Chris Gianelloni"}),", CEO of Blink Labs, the team behind Dingo, spent the afternoon shipping ARM64 Docker images, magnificently unbothered."]}),"\n",(0,a.jsx)(t.p,{children:"The halt lasted less than an hour on our infrastructure. The signature scheme did exactly what it was designed to do. It caught a bad signature. We just overreacted."}),"\n",(0,a.jsx)(t.h2,{id:"the-red-team-is-already-inside",children:"The red team is already inside"}),"\n",(0,a.jsxs)(t.p,{children:["One node on MusashiNet exists purely to hurt us. ",(0,a.jsx)(t.strong,{children:"Piranha"})," is the red team's node, written in Rust, and it connects like any other peer with a single purpose: break the protocol or die trying. Its attacks come straight from our ",(0,a.jsx)(t.a,{href:"https://github.com/input-output-hk/ouroboros-leios/blob/main/docs/threat-model.md",children:"published threat model"}),": T20, withholding an endorser block it had already announced; T27, partitioning the network to split mempools; T10, sitting on the committee and declining to vote."]}),"\n",(0,a.jsxs)(t.p,{children:["The verdict so far, from ",(0,a.jsx)(t.strong,{children:"Chris Tilt"}),", our red team lead:"]}),"\n",(0,a.jsxs)(t.blockquote,{children:["\n",(0,a.jsx)(t.p,{children:"Some attacks were possible, but so far we've found the Leios protocol to be robust against attack, with degradation proportional to stake. So far, there have been no discoveries that compromise the underlying safety of the Praos layer."}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:"The heaviest of it is still ahead, in Fire and in Wind."}),"\n",(0,a.jsx)(t.h2,{id:"water-same-design-many-configurations",children:"Water: same design, many configurations"}),"\n",(0,a.jsx)(t.p,{children:"Earth asked whether the prototype survives contact with reality. It does."}),"\n",(0,a.jsxs)(t.p,{children:["It is still a prototype: the mempool replacement is in review, bottlenecks remain, the pipeline is still being completed. But all of it was found and fixed in the open. ",(0,a.jsx)(t.strong,{children:"The design never failed."})," And the questions that research and simulation could not answer are being answered in the only place they can be: on real machines, across real distances, by real operators."]}),"\n",(0,a.jsx)(t.p,{children:"Water opens now on a fresh chain, and Water takes the shape of whatever contains it: parameter exploration, alternative component implementations starting with that mempool, and real BLS keys as the way into the voting committee. The hunt for Leios's actual limits begins here."}),"\n",(0,a.jsxs)(t.p,{children:["The rewards program is live with it. We reward operators who run MusashiNet nodes and share the data their machines see, because the sharpest questions left can only be answered from hardware we do not own, in places we did not choose. Pools that forged blocks during the Earth phase are eligible for a retroactive reward, judged from a snapshot taken before the reset. The ",(0,a.jsx)(t.a,{href:"https://leios.cardano-scaling.org/docs/testnet/rewards-program/",children:"rewards program page"})," explains the steps."]}),"\n",(0,a.jsx)(t.p,{children:"Cardano took the trilemma in the right order: security first, decentralization second, scale last. Leios is the scale leg, and it is training in public now. If your project needs security you can reason about and an ecosystem that builds in the open, come build on Cardano."}),"\n",(0,a.jsx)(t.p,{children:"The Dojo is open. Come train with us."})]})}function c(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(l,{...e})}):l(e)}},220(e,t,n){n.d(t,{A:()=>o});const o=n.p+"assets/images/musahi-earth-87aed088b0067bcd975636788d809f26.jpg"},8453(e,t,n){n.d(t,{R:()=>i,x:()=>r});var o=n(6540);const a={},s=o.createContext(a);function i(e){const t=o.useContext(s);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:i(e.components),o.createElement(s.Provider,{value:t},e.children)}},250(e){e.exports=JSON.parse('{"permalink":"/blog/musashinet-earth-phase","source":"@site/blog/2026-08-20-musashinet-earth-phase.md","title":"Earth phase, 6x mainnet throughput without even trying","description":"Forty-one days of MusashiNet\'s Earth phase \u2014 what the first public Leios testnet phase proved, what broke, how it was fixed in the open, and what comes next in Water.","date":"2026-08-20T00:00:00.000Z","tags":[{"inline":false,"label":"Testnet","permalink":"/blog/tags/testnet","description":"Posts about the Leios public testnet"},{"inline":false,"label":"MusashiNet","permalink":"/blog/tags/musashinet","description":"News from MusashiNet, the Leios public testnet"},{"inline":false,"label":"Leios","permalink":"/blog/tags/leios","description":"Posts about the Ouroboros Leios protocol"},{"inline":false,"label":"Throughput","permalink":"/blog/tags/throughput","description":"Posts about Cardano throughput and scaling"}],"readingTime":15.37,"hasTruncateMarker":true,"authors":[{"name":"Carlos LopezDeLara","url":"https://github.com/CarlosLopezDeLara","imageURL":"https://avatars.githubusercontent.com/u/64222734?v=4","key":"carlos","page":null}],"frontMatter":{"title":"Earth phase, 6x mainnet throughput without even trying","description":"Forty-one days of MusashiNet\'s Earth phase \u2014 what the first public Leios testnet phase proved, what broke, how it was fixed in the open, and what comes next in Water.","slug":"musashinet-earth-phase","authors":["carlos"],"tags":["testnet","musashinet","leios","throughput"]},"unlisted":false,"nextItem":{"title":"Welcome to the Musashi Dojo","permalink":"/blog/why-leios"}}')}}]);